"""Red-team INDEPENDENT reimplementation (no import of the Executor's modules).
EC over F_p, group structure, coordinate map, exact convolution, character spectrum."""
import numpy as np, hashlib, math

def legendre(a,p):
    a%=p
    if a==0: return 0
    return 1 if pow(a,(p-1)//2,p)==1 else -1

def sqrt_mod(a,p):
    # Tonelli-Shanks (independent of executor's table build)
    a%=p
    if a==0: return 0
    if legendre(a,p)!=1: return None
    if p%4==3: return pow(a,(p+1)//4,p)
    q=p-1; s=0
    while q%2==0: q//=2; s+=1
    z=2
    while legendre(z,p)!=-1: z+=1
    m=s; c=pow(z,q,p); t=pow(a,q,p); r=pow(a,(q+1)//2,p)
    while t!=1:
        i=0; t2=t
        while t2!=1: t2=t2*t2%p; i+=1
        b=pow(c,1<<(m-i-1),p)
        m=i; c=b*b%p; t=t*c%p; r=r*b%p
    return r

def ec_add(P,Q,A,p):
    if P is None: return Q
    if Q is None: return P
    x1,y1=P; x2,y2=Q
    if x1==x2 and (y1+y2)%p==0: return None
    if P==Q: lam=(3*x1*x1+A)*pow(2*y1,p-2,p)%p
    else:    lam=(y2-y1)*pow((x2-x1)%p,p-2,p)%p
    x3=(lam*lam-x1-x2)%p; y3=(lam*(x1-x3)-y1)%p
    return (x3,y3)

def ec_scal(k,P,A,p):
    R=None; Q=P
    while k>0:
        if k&1: R=ec_add(R,Q,A,p)
        Q=ec_add(Q,Q,A,p); k>>=1
    return R

def enumerate_and_fb(A,B,p):
    """Return (all_points, fb_pool) with fb_pool = ascending-x stream of points
    whose f(x) is a NONZERO QR, both roots, exactly as curve.factor_base_x_coords."""
    pts=[]; fb=[]
    for x in range(p):
        fx=(x*x*x+A*x+B)%p
        if fx==0:
            pts.append((x,0)); continue
        if legendre(fx,p)==1:
            y=sqrt_mod(fx,p)
            pts.append((x,y)); pts.append((x,(-y)%p))
            fb.append((x,y));  fb.append((x,(-y)%p))
    return pts,fb

def factorize(n):
    f={}; d=2
    while d*d<=n:
        while n%d==0: f[d]=f.get(d,0)+1; n//=d
        d+=1
    if n>1: f[n]=f.get(n,0)+1
    return sorted(f.items())

def point_order(P,N,fac,A,p):
    if P is None: return 1
    o=N
    for (q,e) in fac:
        for _ in range(e):
            if o%q: break
            if ec_scal(o//q,P,A,p) is None: o//=q
            else: break
    return o

def group_structure(pts,A,p):
    N=len(pts)+1
    fac=factorize(N)
    orders=[point_order(P,N,fac,A,p) for P in pts]
    n2=max(orders); n1=N//n2
    assert N%n2==0 and n2%n1==0,(n1,n2,N)
    G1=pts[orders.index(n2)]
    G2=None
    if n1>1:
        span=set(); cur=None
        for _ in range(n2): span.add(cur); cur=ec_add(cur,G1,A,p)
        for P,o in zip(pts,orders):
            if o==n1 and P not in span: G2=P; break
        assert G2 is not None
    return n1,n2,G1,G2

def coord_map(N,A,p,n1,n2,G1,G2):
    pc={None:(0,0)}; base=None
    for k1 in range(n1):
        cur=base
        for k2 in range(n2):
            if not(k1==0 and k2==0):
                assert cur not in pc,"collision"
                pc[cur]=(k1,k2)
            cur=ec_add(cur,G1,A,p)
        base=ec_add(base,G2,A,p) if G2 is not None else None
        if G2 is None and k1==0: break
    assert len(pc)==N,(len(pc),N)
    return pc

def ind(coords,n1,n2):
    g=np.zeros((n1,n2),dtype=np.int64)
    for a,b in coords: g[a,b]+=1
    return g

def stats(coords,n1,n2,N,F,ms=(2,3,4)):
    cur=ind(coords,n1,n2); tower={1:cur}
    for m in range(2,max(ms)+1):
        out=np.zeros_like(cur)
        for da,db in coords: out+=np.roll(np.roll(cur,da,0),db,1)
        cur=out; tower[m]=cur
    Shat=np.fft.fft2(ind(coords,n1,n2).astype(np.complex128))
    mag=np.abs(Shat).copy(); mag[0,0]=-1.0
    C=float(mag.max())
    out={'C':C,'C_over_F':C/F}
    for m in ms:
        arr=tower[m]; tot=int(arr.sum())
        sumsq=int((arr.astype(object)**2).sum())
        out[m]={'var':(sumsq*N-tot*tot)/(N*N),
                'max_rel_dev':float(np.max(np.abs(arr.astype(np.float64)-(F**m)/N))/((F**m)/N))}
    return out

class Drawer:
    def __init__(s,domain,label,p,m,di,c=0):
        s.d,s.l,s.p,s.m,s.i,s.c=domain,label,p,m,di,c
    def draw(s,M):
        lim=(2**256//M)*M
        while True:
            h=int.from_bytes(hashlib.sha256(f"{s.d}|{s.l}|{s.p}|{s.m}|{s.i}|{s.c}".encode()).digest(),'big')
            s.c+=1
            if h<lim: return h%M

def draw_symmetric_null(pts,p,F,domain,m,di):
    dr=Drawer(domain,"null-subset",p,m,di)
    chosen=set(); guard=0
    while len(chosen)<F:
        guard+=1
        if guard>200*F+1000: raise RuntimeError("reject loop")
        P=pts[dr.draw(len(pts))]
        Q=(P[0],(-P[1])%p)
        if P in chosen: continue
        if P==Q:
            if F-len(chosen)==1: chosen.add(P)
            continue
        if len(chosen)+2>F: continue
        chosen.add(P); chosen.add(Q)
    return list(chosen)

def ladder_F(N,denom):
    t=max(2,N//denom); return t-t%2
